{
  global:
    extern "C++" {
        *gluten::*;
        *facebook::velox::*;
        *fmt::*;
        *folly::*;
        *protobuf::*;
        *substrait::*;
        # gflags internals (fLB/fLI32/fLI64/fLU64/fLD/fLS namespaces hold
        # FLAGS_*, FLAGS_no*, and override helpers for each flag type).
        # Exported so downstream executables / plugins that use velox
        # flags directly (e.g. FLAGS_velox_memory_leak_check_enabled via
        # memory::MemoryManager::initialize) can resolve them against
        # libgluten.so at link time. Without this, velox's static archive
        # would have to be re-linked into every consumer, re-registering
        # every flag and FATAL-ing at startup.
        *fLB::*;
        *fLI32::*;
        *fLI64::*;
        *fLU64::*;
        *fLD::*;
        *fLS::*;
        # rmm / cudf inline functions with function-local static state
        # (rmm::mr::detail::get_map, get_ref_map, initial_resource; cudf
        # default-stream pool; etc.). Without these in the global list,
        # the `local: *;` line demotes them to LOCAL BSS, breaking dedup
        # against libcudf.so / librmm.so which export the same symbols
        # as STB_GNU_UNIQUE. Result: each .so has its own copy of the
        # per-device-resource map, and GpuMemoryTracker installed via
        # `rmm::mr::set_current_device_resource(tracker)` only updates
        # libgluten.so's private map; libcudf.so's map stays empty and
        # cuDF's reader_impl falls back to initial_resource() → 42K
        # cudaMalloc bypass tracker. (See option3 GpuMemoryTracker
        # ODR investigation 2026-04-29.)
        *rmm::*;
        *cudf::*;
    };

    Java_org_apache_gluten_*;
    JNI_OnLoad;
    JNI_OnUnload;
  local:
    # Hide all other symbols except the above global symbols.
    *;
};
